#include <bits/stdc++.h>
using namespace std; using L=long long;
int main(int argc,char**argv){int n;cin>>n;vector<int> base(n);for(auto &r:base)cin>>r; L target=atoll(argv[1]); L pair_c=atoll(argv[3]),pair_f=atoll(argv[4]);int maxflip=atoi(argv[2]); int N=1<<n,full=N-1; vector<pair<int,int>> es;for(int i=0;i<n;i++)for(int j=i+1;j<n;j++)es.push_back({i,j});vector<L>d(N*n),s(N*n),h(N),fs(N),qs(N);long long cases=0,strongs=0,hits=0,pairs=0;auto run=[&](int a,int b){auto r=base;for(int k:{a,b})if(k>=0){auto[i,j]=es[k];r[i]^=1<<j;r[j]^=1<<i;}cases++;int terminal=full;for(int start=0;start<n;start++){int reach=1<<start,old=-1;while(old!=reach){old=reach;for(int i=0;i<n;i++)if(reach>>i&1)reach|=r[i];}terminal &= reach;}strongs++;fill(d.begin(),d.end(),0);fill(s.begin(),s.end(),0);h[0]=1;for(int m=1;m<N;m++){L ht=0;for(int v=0;v<n;v++)if(m>>v&1){int sub=m^(1<<v);L de=0,st=0;if(!sub)de=st=1;else{for(int u=0;u<n;u++)if(sub>>u&1){if(r[v]>>u&1)st+=s[sub*n+u];else de+=d[sub*n+u];}}d[m*n+v]=de;s[m*n+v]=st;ht+=de;}h[m]=ht;}if(h[full]>=target)return;vector<L>f(n);for(int m=1;m<N;m++)for(int v=0;v<n;v++)if(m>>v&1)f[v]+=d[m*n+v]*h[full^m];vector<L>j(n*n);for(int u=0;u<n;u++)if(f[u]<=target-h[full])for(int v=u+1;v<n;v++)if(f[v]<=target-h[full]){L val=0;for(int m=1;m<N;m++)if((m>>u&1)&&!(m>>v&1))val+=d[m*n+u]*s[(full^m)*n+v]+s[m*n+u]*d[(full^m)*n+v];j[u*n+v]=j[v*n+u]=val;}
 fs[0]=qs[0]=0;for(int w=1;w<N;w++){int v=__builtin_ctz(w),p=w^(1<<v);fs[w]=fs[p]+f[v];if(fs[w]>target-h[full])continue;L q=qs[p];for(int u=0;u<n;u++)if(p>>u&1)q+=j[v*n+u];qs[w]=q;if(!(w&terminal))continue;L intercept=h[full]-q;if((intercept==pair_c||intercept==pair_c+2)&&fs[w]==pair_f){pairs++;cout<<"{\"pair_target\":true,\"a\":"<<a<<",\"b\":"<<b<<",\"W\":"<<w<<"}\n";}for(auto[ha,pa]:vector<pair<L,L>>{{1,32},{3,48},{5,64},{9,84},{11,100},{13,104},{15,108},{15,120}}){L val=intercept*ha+fs[w]*pa;if(val==target){hits++;cout<<"{\"a\":"<<a<<",\"b\":"<<b<<",\"W\":"<<w<<",\"prefix_H\":"<<ha<<",\"prefix_P2\":"<<pa<<",\"h\":"<<h[full]<<",\"J\":"<<q<<",\"F\":"<<fs[w]<<",\"target\":"<<val<<"}\n";cout.flush();}}}
};run(-1,-1);if(maxflip>=1)for(int a=0;a<(int)es.size();a++)run(a,-1);if(maxflip>=2)for(int a=0;a<(int)es.size();a++)for(int b=a+1;b<(int)es.size();b++)run(a,b);cerr<<"{\"cases\":"<<cases<<",\"suffixes_evaluated\":"<<strongs<<",\"hits\":"<<hits<<",\"pair_targets\":"<<pairs<<"}\n";}
